   819  ** Check whether new instruction 'newpc' is in a different line from
   820  ** previous instruction 'oldpc'. More often than not, 'newpc' is only
   821  ** one or a few instructions after 'oldpc' (it must be after, see
   822  ** caller), so try to avoid calling 'luaG_getfuncline'. If they are
   823  ** too far apart, there is a good chance of a ABSLINEINFO in the way,
   824  ** so it goes directly to 'luaG_getfuncline'.
   825  */
   826  static int changedline (const Proto *p, int oldpc, int newpc) {
   827    if (p->lineinfo == NULL)  /* no debug information? */
   828      return 0;
   829    if (newpc - oldpc < MAXIWTHABS / 2) {  /* not too far apart? */
   830      int delta = 0;  /* line diference */
   831      int pc = oldpc;
   832      for (;;) {
   833        int lineinfo = p->lineinfo[++pc];
   834        if (lineinfo == ABSLINEINFO)
   835          break;  /* cannot compute delta; fall through */
   836        delta += lineinfo;
   837        if (pc == newpc)
   838          return (delta != 0);  /* delta computed successfully */
   839      }
